(function(){'use strict';
  var CHECKOUT_CONFIG={
    baseUrl:'https://pay.hotmart.com/T108465363N',
    fixedParams:{checkoutMode:'10'},
    allowedTrackingParams:['utm_source','utm_medium','utm_campaign','utm_content','utm_term','src','sck','xcod']
  };
  function buildCheckoutUrl(currentHref){
    var target=new URL(CHECKOUT_CONFIG.baseUrl);
    Object.keys(CHECKOUT_CONFIG.fixedParams).forEach(function(key){
      target.searchParams.set(key,CHECKOUT_CONFIG.fixedParams[key]);
    });
    var existingParams=null;
    try{
      if(currentHref){
        var parsed=new URL(currentHref,window.location.href);
        if(parsed.origin+parsed.pathname===CHECKOUT_CONFIG.baseUrl){
          existingParams=parsed.searchParams;
        }
      }
    }catch(e){}
    var pageParams=new URLSearchParams(window.location.search);
    CHECKOUT_CONFIG.allowedTrackingParams.forEach(function(param){
      var val=existingParams?existingParams.get(param):null;
      if(!val)val=pageParams.get(param);
      if(val&&val!=='null'&&val!=='undefined'){
        target.searchParams.set(param,val);
      }
    });
    return target.toString();
  }
  function syncCheckoutLinks(){
    document.querySelectorAll('a[data-checkout]').forEach(function(link){
      link.removeAttribute('target');
      link.setAttribute('href',buildCheckoutUrl(link.getAttribute('href')));
      if(!link.dataset.checkoutBound){
        link.dataset.checkoutBound='1';
        link.addEventListener('click',function(){
          link.setAttribute('href',buildCheckoutUrl(link.getAttribute('href')));
        });
      }
    });
  }
  syncCheckoutLinks();
  window.addEventListener('load',syncCheckoutLinks,{once:true});

  var countdown=document.querySelector('[data-countdown]');
  var lastCountdownMinutes=null;
  function pad(value){return String(Math.max(0,value)).padStart(2,'0');}
  function tick(){
    if(!countdown)return;
    var target=new Date(countdown.dataset.deadline).getTime();
    var distance=Math.max(0,target-Date.now());
    var totalMinutes=Math.floor(distance/60000);
    var days=Math.floor(totalMinutes/1440);
    var hours=Math.floor((totalMinutes%1440)/60);
    var minutes=totalMinutes%60;
    if(lastCountdownMinutes!==null&&lastCountdownMinutes!==totalMinutes){
      countdown.classList.remove('is-ticking');
      void countdown.offsetWidth;
      countdown.classList.add('is-ticking');
    }
    lastCountdownMinutes=totalMinutes;
    countdown.querySelector('[data-days]').textContent=pad(days);
    countdown.querySelector('[data-hours]').textContent=pad(hours);
    countdown.querySelector('[data-minutes]').textContent=pad(minutes);
  }
  tick();setInterval(tick,30000);

  var sticky=document.querySelector('[data-sticky-cta]');
  var hero=document.querySelector('.hero');
  if(sticky&&hero&&'IntersectionObserver' in window){
    new IntersectionObserver(function(entries){sticky.classList.toggle('is-visible',!entries[0].isIntersecting);},{threshold:.08}).observe(hero);
  }

  document.querySelectorAll('details').forEach(function(detail){
    detail.addEventListener('toggle',function(){if(!detail.open)return;document.querySelectorAll('details[open]').forEach(function(other){if(other!==detail)other.removeAttribute('open');});});
  });

  var revealItems=document.querySelectorAll('.reveal');
  if('IntersectionObserver' in window){
    var revealObserver=new IntersectionObserver(function(entries,observer){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}});},{threshold:.14});
    revealItems.forEach(function(item){revealObserver.observe(item);});
  }else{revealItems.forEach(function(item){item.classList.add('is-visible');});}
})();
(function(){
 var rail=document.querySelector('#whatsapp-conversas');if(!rail)return;
 var slides=Array.from(rail.children),dots=Array.from(document.querySelectorAll('[data-chat-index]')),index=0,timer;
 function update(){dots.forEach(function(d,i){d.setAttribute('aria-current',String(i===index));});}
 function go(i){index=(i+slides.length)%slides.length;rail.scrollTo({left:slides[index].offsetLeft-slides[0].offsetLeft,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});update();}
 document.querySelector('[data-chat-prev]').onclick=function(){go(index-1);};document.querySelector('[data-chat-next]').onclick=function(){go(index+1);};dots.forEach(function(d,i){d.onclick=function(){go(i);};});
 rail.addEventListener('keydown',function(e){if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();go(index+(e.key==='ArrowRight'?1:-1));}});
 rail.addEventListener('scroll',function(){clearTimeout(timer);timer=setTimeout(function(){var x=rail.scrollLeft;index=slides.reduce(function(best,s,i){return Math.abs(s.offsetLeft-slides[0].offsetLeft-x)<Math.abs(slides[best].offsetLeft-slides[0].offsetLeft-x)?i:best;},0);update();},120);});
 var inView=false;new IntersectionObserver(function(entries){inView=entries[0].isIntersecting;},{threshold:.2}).observe(rail);
 setInterval(function(){if(inView&&!document.hidden)go(index+1);},6500);
})();

(function(){var link=document.querySelector('[data-scroll-offer]'),offer=document.getElementById('oferta');if(!link||!offer)return;link.addEventListener('click',function(e){if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();var bar=document.querySelector('[data-promo-bar]'),offset=bar?bar.getBoundingClientRect().height:0;window.scrollTo({top:Math.max(0,offer.getBoundingClientRect().top+window.scrollY-offset-16),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});})();

(function(){
 var note=document.querySelector('[data-hero-note]'),text=document.querySelector('[data-hero-note-text]');if(!note||!text)return;
 var reduced=window.matchMedia('(prefers-reduced-motion: reduce)'),messages=['Garantia de satisfação de 15 dias para comprar com tranquilidade.','Acesso imediato após a confirmação','Pagamento seguro pela Hotmart'],index=0,interval,transition;
 note.addEventListener('animationend',function(e){if(e.target===note)note.classList.add('is-settled');},{once:true});
 function stop(){clearInterval(interval);clearTimeout(transition);note.classList.remove('is-changing');}
 function start(){stop();if(reduced.matches)return;interval=setInterval(function(){if(document.hidden)return;note.classList.add('is-settled');note.classList.add('is-changing');transition=setTimeout(function(){index=(index+1)%messages.length;text.textContent=messages[index];note.classList.remove('is-changing');},250);},3800);}
 if(reduced.addEventListener)reduced.addEventListener('change',start);start();
})();
(function(){
 'use strict';
 var bar=document.querySelector('[data-promo-bar]');if(!bar)return;
 var clock=bar.querySelector('[data-promo-clock]'),message=bar.querySelector('[data-promo-message]'),label=bar.querySelector('[data-promo-label]'),status=bar.querySelector('[data-promo-status]');
 var KEY='pqr:christmas-2026:bonus-window:v1',DURATION=15*60*1000,deadline,lastSeconds=null,interval;
 function size(){document.documentElement.style.setProperty('--promo-height',Math.ceil(bar.getBoundingClientRect().height)+'px');}
 if('ResizeObserver' in window)new ResizeObserver(size).observe(bar);else window.addEventListener('resize',size);size();
 function unavailable(){bar.classList.add('is-unavailable');message.textContent='3 BÓNUS INCLUÍDOS NA SUA COMPRA';status.textContent='Contagem indisponível.';size();}
 try{
  var saved=localStorage.getItem(KEY);
  if(saved!==null){
   var data=JSON.parse(saved);
   if(!data||!Number.isFinite(data.startedAt)||!Number.isFinite(data.expiresAt)||data.expiresAt-data.startedAt!==DURATION||data.expiresAt>Date.now()+DURATION){unavailable();return;}
   deadline=data.expiresAt;
  }else{
   var start=Date.now();deadline=start+DURATION;
   localStorage.setItem(KEY,JSON.stringify({startedAt:start,expiresAt:deadline}));
  }
 }catch(e){unavailable();return;}
 function tick(){
  var seconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));
  if(seconds===lastSeconds)return;lastSeconds=seconds;
  if(seconds===0){
   clock.textContent='Prazo terminado';clock.setAttribute('aria-label','Prazo promocional terminado');clock.dateTime=new Date(deadline).toISOString();
   bar.classList.add('is-expired');message.textContent='O PRAZO DESTA PROMOÇÃO TERMINOU';label.textContent='Estado da oferta:';
   status.textContent='O prazo promocional terminou.';clearInterval(interval);size();return;
  }
  var mins=Math.floor(seconds/60),secs=seconds%60;
  clock.textContent=String(mins).padStart(2,'0')+':'+String(secs).padStart(2,'0');clock.dateTime='PT'+mins+'M'+secs+'S';clock.setAttribute('aria-label',mins+' minutos e '+secs+' segundos restantes');
 }
 interval=setInterval(tick,1000);tick();
 document.addEventListener('visibilitychange',function(){if(!document.hidden)tick();});
 window.addEventListener('pageshow',tick);
 window.addEventListener('storage',function(e){if(e.key===KEY){window.location.reload();}});
})();
